class PagedResponse<T> { const PagedResponse({required this.content,required this.page,required this.size,required this.totalElements,required this.totalPages,required this.last}); final List<T> content; final int page; final int size; final int totalElements; final int totalPages; final bool last; factory PagedResponse.fromJson(Map<String,dynamic> json,T Function(Map<String,dynamic>) mapper)=>PagedResponse(content:(json['content'] as List<dynamic>? ?? const []).map((e)=>mapper(e as Map<String,dynamic>)).toList(growable:false),page:(json['page'] as num?)?.toInt() ?? 0,size:(json['size'] as num?)?.toInt() ?? 20,totalElements:(json['totalElements'] as num?)?.toInt() ?? 0,totalPages:(json['totalPages'] as num?)?.toInt() ?? 0,last:json['last'] as bool? ?? true); }
